(5692579, 828246, 49954, '<td valign="top">Ok.  Title could work as a movie and the image of two boats in choppy seas draws interest.  However, not in poster format and the image itself is of good content, but not well taken.</td>', 'Ok.  Title could work as a movie and the image of two boats in choppy seas draws interest.  However, not in poster format and the image itself is of good content, but not well taken.', '2009-10-19 17:34:27.000000', NULL, 1),
(5692581, 828157, 89230, '<td valign="top">Wicked effect. Well done!</td>', 'Wicked effect. Well done!', '2009-10-19 17:34:52.000000', NULL, 1),
